public class Operators {
    public static void main(String[] args) {
        int a = 7, b = 2;
        System.out.println(a / b + " " + a % b);   // 3 1

        int x = 5;
        String result = (x > 0) ? "positive" : "non-positive";
        System.out.println(result);                 // positive

        String s1 = "cat", s2 = new String("cat");
        System.out.println(s1 == s2);                // false — reference comparison
        System.out.println(s1.equals(s2));           // true — content comparison
    }
}
